import{_ as d,a0 as p,w as l,s,I as r,x as e,a1 as n,A as o,ao as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const c=JSON.parse('{"title":"如何在 CentOS 中设置 NTP 服务器 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 CentOS 中设置 NTP 服务器 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 CentOS 中设置 NTP 服务器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 CentOS 中设置 NTP 服务器 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150427 How to set up NTP server in CentOS","title":"如何在 CentOS 中设置 NTP 服务器","tag":"201506","desc":""},"relativePath":"201506/20150427 How to set up NTP server in CentOS.md","filePath":"[post].md"}'),m={name:"201506/20150427 How to set up NTP server in CentOS.md"};function T(P,t,u,N,h,f){const a=p("Link");return l(),s("div",null,[t[18]||(t[18]=r("h1",{id:"如何在-centos-中设置-ntp-服务器",tabindex:"-1"},[e("如何在 CentOS 中设置 NTP 服务器 "),r("a",{class:"header-anchor",href:"#如何在-centos-中设置-ntp-服务器","aria-label":"Permalink to “如何在 CentOS 中设置 NTP 服务器”"},"​")],-1)),t[19]||(t[19]=r("p",null,"网络时间协议(NTP)用来同步网络上不同主机的系统时间。你管理的所有主机都可以和一个指定的被称为 NTP 服务器的时间服务器同步它们的时间。而另一方面，一个 NTP 服务器会将它的时间和任意公共 NTP 服务器，或者你选定的服务器同步。由 NTP 管理的所有系统时钟都会同步精确到毫秒级。",-1)),t[20]||(t[20]=r("p",null,"在公司环境中，如果他们不想为 NTP 传输打开防火墙，就有必要设置一个内部 NTP 服务器，然后让员工使用内部服务器而不是公共 NTP 服务器。在这个指南中，我们会介绍如何将一个 CentOS 系统配置为 NTP 服务器。在介绍详细内容之前，让我们先来简单了解一下 NTP 的概念。",-1)),t[21]||(t[21]=r("h3",{id:"为什么我们需要-ntp",tabindex:"-1"},[e("为什么我们需要 NTP? "),r("a",{class:"header-anchor",href:"#为什么我们需要-ntp","aria-label":"Permalink to “为什么我们需要 NTP?”"},"​")],-1)),t[22]||(t[22]=r("p",null,"由于制造工艺多种多样，所有的(非原子)时钟并不按照完全一致的速度行走。有一些时钟走的比较快而有一些走的比较慢。因此经过很长一段时间以后，一个时钟的时间慢慢的和其它的发生偏移，这就是常说的 “时钟漂移” 或 “时间漂移”。为了将时钟漂移的影响最小化，使用 NTP 的主机应该周期性地和指定的 NTP 服务器交互以保持它们的时钟同步。",-1)),r("p",null,[t[2]||(t[2]=e("在不同的主机之间进行时间同步对于计划备份、",-1)),n(a,{href:"http://xmodulo.com/how-to-compile-and-install-snort-from-source-code-on-ubuntu.html"},{default:o(()=>[...t[0]||(t[0]=[e("入侵检测",-1)])]),_:1}),t[3]||(t[3]=e("记录、",-1)),n(a,{href:"http://xmodulo.com/how-to-install-hdfs-and-hadoop-using.html"},{default:o(()=>[...t[1]||(t[1]=[e("分布式任务调度",-1)])]),_:1}),t[4]||(t[4]=e("或者事务订单管理来说是很重要的事情。它甚至应该作为日常任务的一部分。",-1))]),t[23]||(t[23]=i(`<h3 id="ntp-的层次结构" tabindex="-1">NTP 的层次结构 <a class="header-anchor" href="#ntp-的层次结构" aria-label="Permalink to “NTP 的层次结构”">​</a></h3><p>NTP 时钟以层次模型组织。层级中的每层被称为一个 <em>stratum（阶层）</em>。stratum 的概念说明了一台机器到授权的时间源有多少 NTP 跳。</p><p><img src="https://farm8.staticflickr.com/7590/16645732413_3b7af58186_c.jpg" alt=""></p><p>Stratum 0 由没有时间漂移的时钟组成，例如原子时钟。这种时钟不能在网络上直接使用。Stratum N (N &gt; 1) 层服务器从 Stratum N-1 层服务器同步时间。Stratum N 时钟能通过网络和彼此互联。</p><p>NTP 支持多达 15 个 stratum 的层级。Stratum 16 被认为是未同步的，不能使用的。</p><h3 id="准备-centos-服务器" tabindex="-1">准备 CentOS 服务器 <a class="header-anchor" href="#准备-centos-服务器" aria-label="Permalink to “准备 CentOS 服务器”">​</a></h3><p>现在让我们来开始在 CentOS 上设置 NTP 服务器。</p><p>首先，我们需要保证正确设置了服务器的时区。在 CentOS 7 中，我们可以使用 timedatectl 命令查看和更改服务器的时区(比如，&quot;Australia/Adelaide&quot;，LCTT 译注：中国可设置为 Asia/Shanghai )</p><pre><code># timedatectl list-timezones | grep Australia
# timedatectl set-timezone Australia/Adelaide
# timedatectl
</code></pre><p><img src="https://farm8.staticflickr.com/7605/16645732463_db75a0bdcd_o.png" alt=""></p><p>继续并使用 yum 安装需要的软件</p><pre><code># yum install ntp
</code></pre><p>然后我们会添加全球 NTP 服务器用于同步时间。</p><pre><code># vim /etc/ntp.conf
</code></pre><hr><pre><code>server 0.oceania.pool.ntp.org
server 1.oceania.pool.ntp.org
server 2.oceania.pool.ntp.org
server 3.oceania.pool.ntp.org
</code></pre><p>默认情况下，NTP 服务器的日志保存在 /var/log/messages。如果你希望使用自定义的日志文件，那也可以指定。</p><pre><code>logfile /var/log/ntpd.log
</code></pre><p>如果你选择自定义日志文件，确保更改了它的属主和 SELinux 环境。</p><pre><code># chown ntp:ntp /var/log/ntpd.log
# chcon -t ntpd_log_t /var/log/ntpd.log
</code></pre><p>现在初始化 NTP 服务并确保把它添加到了开机启动。</p><pre><code># systemctl restart ntp
# systemctl enable ntp
</code></pre><h3 id="验证-ntp-server-时钟" tabindex="-1">验证 NTP Server 时钟 <a class="header-anchor" href="#验证-ntp-server-时钟" aria-label="Permalink to “验证 NTP Server 时钟”">​</a></h3><p>我们可以使用 ntpq 命令来检查本地服务器的时钟如何通过 NTP 同步。</p><p><img src="https://farm9.staticflickr.com/8713/16645732513_1823736ca8_b.jpg" alt=""></p><p>下面的表格解释了输出列。</p><table id="content"><tbody><tr><td>remote</td><td>源在 ntp.conf 中定义。‘*’ 表示当前使用的，也是最好的源；‘+’ 表示这些源可作为 NTP 源；‘-’ 标记的源是不可用的。</td></tr><tr><td>refid</td><td>用于和本地时钟同步的远程服务器的 IP 地址。</td></tr><tr><td>st</td><td>Stratum（阶层）</td></tr><tr><td>t</td><td>类型。 &#39;u&#39; 表示单播(unicast)。其它值包括本地(local)、多播(multicast)、广播(broadcast)。</td></tr><tr><td>when</td><td>自从上次和服务器交互后经过的时间(以秒数计)。</td></tr><tr><td>poll</td><td>和服务器的轮询间隔，以秒数计。</td></tr><tr><td>reach</td><td>表示和服务器交互是否有任何错误的八进制数。值 337 表示 100% 成功（即十进制的255）。</td></tr><tr><td>delay</td><td>服务器和远程服务器来回的时间。</td></tr><tr><td>offset</td><td>我们服务器和远程服务器的时间差异，以毫秒数计。</td></tr><tr><td>jitter</td><td>两次取样之间平均时差，以毫秒数计。</td></tr></tbody></table><h3 id="控制到-ntp-服务器的访问" tabindex="-1">控制到 NTP 服务器的访问 <a class="header-anchor" href="#控制到-ntp-服务器的访问" aria-label="Permalink to “控制到 NTP 服务器的访问”">​</a></h3><p>默认情况下，NTP 服务器允许来自所有主机的查询。如果你想过滤进来的 NTP 同步连接，你可以在你的防火墙中添加规则过滤流量。</p><pre><code># iptables -A INPUT -s 192.168.1.0/24 -p udp --dport 123 -j ACCEPT
# iptables -A INPUT -p udp --dport 123 -j DROP
</code></pre><p>该规则允许从 192.168.1.0/24 来的 NTP 流量(端口 UDP/123)，任何其它网络的流量会被丢弃。你可以根据需要更改规则。</p><h3 id="配置-ntp-客户端" tabindex="-1">配置 NTP 客户端 <a class="header-anchor" href="#配置-ntp-客户端" aria-label="Permalink to “配置 NTP 客户端”">​</a></h3><h4 id="_1-linux" tabindex="-1">1. Linux <a class="header-anchor" href="#_1-linux" aria-label="Permalink to “1. Linux”">​</a></h4><p>NTP 客户端主机需要 ntpupdate 软件包来和服务器同步时间。可以轻松地使用 yum 或 apt-get 安装这个软件包。安装完软件包之后，用服务器的 IP 地址运行下面的命令。</p><pre><code># ntpdate &lt;server-IP-address&gt;
</code></pre><p>基于 RHEL 和 Debian 的系统命令都相同。</p><h4 id="_2-windows" tabindex="-1">2. Windows <a class="header-anchor" href="#_2-windows" aria-label="Permalink to “2. Windows”">​</a></h4><p>如果你正在使用 Windows，在日期和时间设置(Date and Time settings)下查找网络时间(Internet Time)。</p><h4 id="_3-cisco-设备" tabindex="-1">3. Cisco 设备 <a class="header-anchor" href="#_3-cisco-设备" aria-label="Permalink to “3. Cisco 设备”">​</a></h4><p>如果你想要同步 Cisco 设备的时间，你可以在全局配置模式下使用下面的命令。</p><pre><code># ntp server &lt;server-IP-address&gt;
</code></pre><p>来自其它厂家的支持 NTP 的设备有自己的用于网络时间的参数。如果你想将设备和 NTP服务器同步时间，请查看设备的说明文档。</p><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to “结论”">​</a></h3><p>总而言之，NTP 是在你的所有主机上同步时钟的一个协议。我们已经介绍了如何设置 NTP 服务器并使支持 NTP 的设备和服务器同步时间。</p><p>希望能对你有所帮助。</p><hr>`,46)),r("p",null,[t[6]||(t[6]=e("via: ",-1)),n(a,{href:"http://xmodulo.com/setup-ntp-server-centos.html"},{default:o(()=>[...t[5]||(t[5]=[e("http://xmodulo.com/setup-ntp-server-centos.html",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=e("作者：",-1)),n(a,{href:"http://xmodulo.com/author/sarmed"},{default:o(()=>[...t[7]||(t[7]=[e("Sarmed Rahman",-1)])]),_:1}),t[11]||(t[11]=e(" 译者：",-1)),n(a,{href:"https://github.com/ictlyh"},{default:o(()=>[...t[8]||(t[8]=[e("ictlyh",-1)])]),_:1}),t[12]||(t[12]=e(" 校对：",-1)),n(a,{href:"https://github.com/wxy"},{default:o(()=>[...t[9]||(t[9]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[15]||(t[15]=e("本文由 ",-1)),n(a,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[13]||(t[13]=[e("LCTT",-1)])]),_:1}),t[16]||(t[16]=e(" 原创翻译，",-1)),n(a,{href:"http://linux.cn/"},{default:o(()=>[...t[14]||(t[14]=[e("Linux中国",-1)])]),_:1}),t[17]||(t[17]=e(" 荣誉推出",-1))])])}const g=d(m,[["render",T]]);export{c as __pageData,g as default};
